var menuScrollPosition=0;function getScrollPosition(){return window.scrollY||window.scrollTop||document.getElementsByTagName("html")[0].scrollTop}function setMenuOpen(a){document.getElementById("site-nav").classList.toggle("open",a);document.querySelector(".nav-toggle").setAttribute("aria-expanded",a)}function foldMenu(){menuScrollPosition=getScrollPosition();setMenuOpen(!document.getElementById("site-nav").classList.contains("open"))}function closeMenuIfOpened(){setMenuOpen(false)}window.addEventListener("scroll",function(b){var a=getScrollPosition();if(Math.abs(a-menuScrollPosition)>250){closeMenuIfOpened()}});function toggleTheme(){var a=document.documentElement.dataset.theme==="dark"?"light":"dark";localStorage.setItem("theme",a);document.documentElement.dataset.theme=a;var b=document.querySelector("iframe.giscus-frame");if(b){b.contentWindow.postMessage({giscus:{setConfig:{theme:a==="dark"?"dark_dimmed":"light"}}},"https://giscus.app")}};